import React, { useEffect, useRef, useCallback, useState } from "react"
import Layout from "../components/layout"

const Chess = typeof window !== "undefined" ? require("chess.js").Chess : null

const BOARD_SIZE = 480
const SQ = BOARD_SIZE / 8
const LIGHT_SQ = "#f0d9b5"
const DARK_SQ = "#b58863"
const HIGHLIGHT_COLOR = "rgba(255, 255, 0, 0.4)"
const LEGAL_DOT_COLOR = "rgba(0, 0, 0, 0.25)"
const ARROW_COLORS = ["rgba(0, 180, 0, 0.6)", "rgba(200, 180, 0, 0.5)", "rgba(200, 120, 0, 0.4)"]
const GAMBIT_COLOR = "rgba(255, 80, 0, 0.6)"

const PIECE_CHARS = {
  K: "\u2654", Q: "\u2655", R: "\u2656", B: "\u2657", N: "\u2658", P: "\u2659",
  k: "\u265A", q: "\u265B", r: "\u265C", b: "\u265D", n: "\u265E", p: "\u265F",
}

const FILES = ["a", "b", "c", "d", "e", "f", "g", "h"]
const RANKS = ["8", "7", "6", "5", "4", "3", "2", "1"]

function squareToCoords(sq, flipped) {
  const file = FILES.indexOf(sq[0])
  const rank = RANKS.indexOf(sq[1])
  const x = flipped ? (7 - file) * SQ : file * SQ
  const y = flipped ? (7 - rank) * SQ : rank * SQ
  return { x, y }
}

function coordsToSquare(cx, cy, flipped) {
  const file = flipped ? 7 - Math.floor(cx / SQ) : Math.floor(cx / SQ)
  const rank = flipped ? 7 - Math.floor(cy / SQ) : Math.floor(cy / SQ)
  if (file < 0 || file > 7 || rank < 0 || rank > 7) return null
  return FILES[file] + RANKS[rank]
}

function parseUciMove(uci) {
  if (!uci || uci.length < 4) return null
  return { from: uci.slice(0, 2), to: uci.slice(2, 4), promotion: uci.length > 4 ? uci[4] : undefined }
}

function formatEval(score) {
  if (score.mate !== undefined) return `M${score.mate}`
  return (score.cp >= 0 ? "+" : "") + (score.cp / 100).toFixed(1)
}

// Create a stockfish worker using the single-threaded build in static/
function createEngine(onMessage) {
  if (typeof window === "undefined") return null
  const worker = new Worker("/stockfish.js")
  worker.onmessage = (e) => onMessage(e.data)
  worker.postMessage("uci")
  return worker
}

function sendToEngine(worker, cmd) {
  if (worker) worker.postMessage(cmd)
}

export default function ChessPage() {
  const canvasRef = useRef(null)
  const gameRef = useRef(null) // { chess, selected, moveHistory, historyIndex, flipped }
  const engineRef = useRef(null) // analysis worker
  const analysisRef = useRef({ depth: 0, lines: [], fen: "" })
  const gambitResultsRef = useRef([])
  const gambitScanRef = useRef({ running: false, progress: "", aborted: false })
  const scanPositionRef = useRef(null) // FEN of position currently being scanned (for phantom display)
  const rafRef = useRef(null)
  const dragRef = useRef(null) // { piece, square, x, y } for drag-and-drop

  const [fen, setFen] = useState("start")
  const [moveList, setMoveList] = useState([])
  const [historyIndex, setHistoryIndex] = useState(0)
  const [selected, setSelected] = useState(null)
  const [flipped, setFlipped] = useState(false)
  const [engineReady, setEngineReady] = useState(false)
  const [evalDisplay, setEvalDisplay] = useState("")
  const [engineLines, setEngineLines] = useState([])
  const [engineDepth, setEngineDepth] = useState(0)
  const [gambitThreshold, setGambitThreshold] = useState(30) // centipawns — how bad a move must be to count as a gambit
  const [maxDepth, setMaxDepth] = useState(16)
  const [lookAhead, setLookAhead] = useState(1) // how many plies deep to search for gambits
  const [branchWidth, setBranchWidth] = useState(5) // how many top moves to explore per ply
  const [scanStatus, setScanStatus] = useState("")
  const [gambitResults, setGambitResults] = useState([])
  const [scanHistory, setScanHistory] = useState([]) // array of { label, results, rootFen }
  const [viewingScanIndex, setViewingScanIndex] = useState(null) // which historical scan is being viewed
  const [inspectedGambit, setInspectedGambit] = useState(null) // index of gambit being inspected

  // Init game
  useEffect(() => {
    if (!Chess) return
    const chess = new Chess()
    gameRef.current = {
      chess,
      selected: null,
      moveHistory: [{ san: null, fen: chess.fen() }],
      historyIndex: 0,
      flipped: false,
    }
    setFen(chess.fen())
  }, [])

  // Init engine
  useEffect(() => {
    if (typeof window === "undefined") return

    const engine = createEngine((msg) => {
      if (msg === "uciok") {
        sendToEngine(engine, "setoption name MultiPV value 3")
        sendToEngine(engine, "isready")
      }
      if (msg === "readyok") {
        setEngineReady(true)
      }
      if (typeof msg === "string" && msg.startsWith("info") && msg.includes(" pv ")) {
        parseAnalysisInfo(msg)
      }
    })
    engineRef.current = engine

    return () => {
      if (engine) engine.terminate()
    }
  }, [])

  // Parse UCI info lines for analysis display
  const parseAnalysisInfo = useCallback((msg) => {
    const a = analysisRef.current
    const depthMatch = msg.match(/\bdepth (\d+)/)
    const pvMatch = msg.match(/ pv (.+)/)
    const scoreMatch = msg.match(/\bscore (cp|mate) (-?\d+)/)
    const multipvMatch = msg.match(/\bmultipv (\d+)/)

    if (!depthMatch || !pvMatch || !scoreMatch) return

    // Suppress display updates during gambit scans (high MultiPV floods the UI)
    if (gambitScanRef.current.running) return

    const depth = parseInt(depthMatch[1])
    const pvMoves = pvMatch[1].split(" ")
    const scoreType = scoreMatch[1]
    const scoreVal = parseInt(scoreMatch[2])
    const pvIndex = multipvMatch ? parseInt(multipvMatch[1]) - 1 : 0
    const score = scoreType === "mate" ? { mate: scoreVal } : { cp: scoreVal }

    if (depth > a.depth || pvIndex === 0) {
      if (pvIndex === 0) a.depth = depth
      if (pvIndex === 0) a.lines = []
    }

    a.lines[pvIndex] = { score, pv: pvMoves, depth }

    // Update display state
    if (pvIndex === 0) {
      const g = gameRef.current
      if (g) {
        // Flip eval sign if black to move
        const turn = g.chess.turn()
        const dispScore = { ...score }
        if (turn === "b" && dispScore.cp !== undefined) dispScore.cp = -dispScore.cp
        if (turn === "b" && dispScore.mate !== undefined) dispScore.mate = -dispScore.mate
        setEvalDisplay(formatEval(dispScore))
      }
      setEngineDepth(depth)
    }

    // Convert lines for display
    const displayLines = a.lines.filter(Boolean).map((line, i) => {
      const g = gameRef.current
      if (!g) return null
      const turn = g.chess.turn()
      const dispScore = { ...line.score }
      if (turn === "b" && dispScore.cp !== undefined) dispScore.cp = -dispScore.cp
      if (turn === "b" && dispScore.mate !== undefined) dispScore.mate = -dispScore.mate

      // Convert UCI moves to SAN for display
      const tempChess = new Chess(g.chess.fen())
      const sanMoves = []
      for (const uci of line.pv.slice(0, 6)) {
        const parsed = parseUciMove(uci)
        if (!parsed) break
        try {
          const move = tempChess.move(parsed)
          if (move) sanMoves.push(move.san)
          else break
        } catch { break }
      }

      return {
        score: formatEval(dispScore),
        moves: sanMoves.join(" "),
        firstMove: line.pv[0],
      }
    }).filter(Boolean)

    setEngineLines(displayLines)
  }, [])

  // Start analysis for current position
  const startAnalysis = useCallback((fenStr) => {
    const engine = engineRef.current
    if (!engine || !engineReady) return
    analysisRef.current = { depth: 0, lines: [], fen: fenStr }
    sendToEngine(engine, "stop")
    sendToEngine(engine, "setoption name MultiPV value 3")
    sendToEngine(engine, "setoption name Skill Level value 20")
    sendToEngine(engine, "position fen " + fenStr)
    sendToEngine(engine, "go depth " + maxDepth)
  }, [engineReady, maxDepth])

  // Trigger analysis on position change
  useEffect(() => {
    if (fen !== "start" && engineReady) {
      startAnalysis(fen)
    }
  }, [fen, engineReady, startAnalysis])

  // Make a move
  const makeMove = useCallback((from, to, promotion) => {
    const g = gameRef.current
    if (!g) return false
    try {
      const move = g.chess.move({ from, to, promotion: promotion || "q" })
      if (!move) return false

      // Truncate future history if navigated back
      g.moveHistory = g.moveHistory.slice(0, g.historyIndex + 1)
      g.moveHistory.push({ san: move.san, fen: g.chess.fen() })
      g.historyIndex = g.moveHistory.length - 1
      g.selected = null

      setFen(g.chess.fen())
      setMoveList(g.moveHistory.map(h => h.san))
      setHistoryIndex(g.historyIndex)
      setSelected(null)
      // Clear live scan results but don't touch scan history
      setGambitResults([])
      gambitResultsRef.current = []
      setViewingScanIndex(null)
      setInspectedGambit(null)

      return true
    } catch {
      return false
    }
  }, [])

  // Navigate history
  const navigateTo = useCallback((index) => {
    const g = gameRef.current
    if (!g || index < 0 || index >= g.moveHistory.length) return
    g.historyIndex = index
    g.chess.load(g.moveHistory[index].fen)
    g.selected = null
    setFen(g.chess.fen())
    setHistoryIndex(index)
    setSelected(null)
  }, [])

  // Handle canvas click
  const handleMouseDown = useCallback((e) => {
    const g = gameRef.current
    if (!g) return
    const rect = canvasRef.current.getBoundingClientRect()
    const scale = BOARD_SIZE / rect.width
    const mx = (e.clientX - rect.left) * scale
    const my = (e.clientY - rect.top) * scale
    const sq = coordsToSquare(mx, my, g.flipped)
    if (!sq) return

    const piece = g.chess.get(sq)

    if (g.selected) {
      // Try to move
      if (makeMove(g.selected, sq)) return
      // If clicked own piece, select it instead
      if (piece && piece.color === g.chess.turn()) {
        g.selected = sq
        setSelected(sq)
        // Start drag
        dragRef.current = { piece: piece.color + piece.type, square: sq, x: mx, y: my }
        return
      }
      // Deselect
      g.selected = null
      setSelected(null)
      return
    }

    if (piece && piece.color === g.chess.turn()) {
      g.selected = sq
      setSelected(sq)
      // Start drag
      dragRef.current = { piece: piece.color + piece.type, square: sq, x: mx, y: my }
    }
  }, [makeMove])

  const handleMouseMove = useCallback((e) => {
    if (!dragRef.current) return
    const rect = canvasRef.current.getBoundingClientRect()
    const scale = BOARD_SIZE / rect.width
    dragRef.current.x = (e.clientX - rect.left) * scale
    dragRef.current.y = (e.clientY - rect.top) * scale
  }, [])

  const handleMouseUp = useCallback((e) => {
    const drag = dragRef.current
    if (!drag) return
    dragRef.current = null
    const g = gameRef.current
    if (!g) return
    const rect = canvasRef.current.getBoundingClientRect()
    const scale = BOARD_SIZE / rect.width
    const mx = (e.clientX - rect.left) * scale
    const my = (e.clientY - rect.top) * scale
    const sq = coordsToSquare(mx, my, g.flipped)
    if (sq && sq !== drag.square) {
      if (makeMove(drag.square, sq)) return
    }
    // If didn't move, keep selected
  }, [makeMove])

  // Keyboard navigation
  useEffect(() => {
    const handler = (e) => {
      const g = gameRef.current
      if (!g) return
      if (e.key === "ArrowLeft") {
        e.preventDefault()
        navigateTo(g.historyIndex - 1)
      } else if (e.key === "ArrowRight") {
        e.preventDefault()
        navigateTo(g.historyIndex + 1)
      } else if (e.key === "f" || e.key === "F") {
        setFlipped(f => {
          g.flipped = !f
          return !f
        })
      } else if (e.key === "Escape") {
        g.selected = null
        setSelected(null)
      }
    }
    window.addEventListener("keydown", handler)
    return () => window.removeEventListener("keydown", handler)
  }, [navigateTo])

  // Draw board
  const draw = useCallback(() => {
    const canvas = canvasRef.current
    const g = gameRef.current
    if (!canvas || !g) return
    const ctx = canvas.getContext("2d")
    const analysis = analysisRef.current
    const gambitRes = gambitResultsRef.current

    // Squares
    for (let rank = 0; rank < 8; rank++) {
      for (let file = 0; file < 8; file++) {
        const isLight = (rank + file) % 2 === 0
        ctx.fillStyle = isLight ? LIGHT_SQ : DARK_SQ
        const displayFile = g.flipped ? 7 - file : file
        const displayRank = g.flipped ? 7 - rank : rank
        ctx.fillRect(displayFile * SQ, displayRank * SQ, SQ, SQ)
      }
    }

    // Coordinate labels
    ctx.font = "bold 10px monospace"
    for (let i = 0; i < 8; i++) {
      const file = g.flipped ? 7 - i : i
      const rank = g.flipped ? 7 - i : i
      // File labels at bottom
      ctx.fillStyle = i % 2 === 0 ? DARK_SQ : LIGHT_SQ
      ctx.textAlign = "left"
      ctx.textBaseline = "bottom"
      ctx.fillText(FILES[file], i * SQ + 2, BOARD_SIZE - 2)
      // Rank labels at left
      ctx.fillStyle = i % 2 === 0 ? LIGHT_SQ : DARK_SQ
      ctx.textAlign = "left"
      ctx.textBaseline = "top"
      ctx.fillText(RANKS[rank], 2, i * SQ + 2)
    }

    // Highlight selected square
    if (g.selected) {
      const { x, y } = squareToCoords(g.selected, g.flipped)
      ctx.fillStyle = HIGHLIGHT_COLOR
      ctx.fillRect(x, y, SQ, SQ)
    }

    // Legal move indicators
    if (g.selected) {
      const moves = g.chess.moves({ square: g.selected, verbose: true })
      for (const move of moves) {
        const { x, y } = squareToCoords(move.to, g.flipped)
        const captured = g.chess.get(move.to)
        if (captured) {
          // Ring for captures
          ctx.strokeStyle = LEGAL_DOT_COLOR
          ctx.lineWidth = 3
          ctx.beginPath()
          ctx.arc(x + SQ / 2, y + SQ / 2, SQ / 2 - 4, 0, Math.PI * 2)
          ctx.stroke()
        } else {
          // Dot for empty squares
          ctx.fillStyle = LEGAL_DOT_COLOR
          ctx.beginPath()
          ctx.arc(x + SQ / 2, y + SQ / 2, SQ / 6, 0, Math.PI * 2)
          ctx.fill()
        }
      }
    }

    // Gambit highlights (only show arrows for immediate gambits, not future-ply ones)
    for (const gb of gambitRes) {
      if (gb.leadingMoves.length > 0) continue
      const { x, y } = squareToCoords(gb.from, g.flipped)
      ctx.fillStyle = GAMBIT_COLOR
      ctx.fillRect(x, y, SQ, SQ)
      // Small arrow to target
      const to = squareToCoords(gb.to, g.flipped)
      drawArrow(ctx, x + SQ / 2, y + SQ / 2, to.x + SQ / 2, to.y + SQ / 2, GAMBIT_COLOR, 4)
    }

    // Determine if we're showing a phantom scan position
    const scanFen = scanPositionRef.current
    const showingPhantom = scanFen && scanFen !== g.chess.fen()
    let phantomBoard = null
    if (showingPhantom) {
      try {
        const phantomChess = new Chess(scanFen)
        phantomBoard = phantomChess.board()
      } catch { /* ignore invalid fen */ }
    }

    // Real pieces (dimmed if phantom overlay is active)
    const board = g.chess.board()
    ctx.textAlign = "center"
    ctx.textBaseline = "middle"
    ctx.font = `${SQ * 0.75}px serif`
    const realAlpha = showingPhantom ? 0.3 : 1.0
    ctx.globalAlpha = realAlpha
    for (let rank = 0; rank < 8; rank++) {
      for (let file = 0; file < 8; file++) {
        const piece = board[rank][file]
        if (!piece) continue
        const sq = FILES[file] + RANKS[rank]
        if (dragRef.current && dragRef.current.square === sq) continue
        const displayFile = g.flipped ? 7 - file : file
        const displayRank = g.flipped ? 7 - rank : rank
        const key = piece.color === "w" ? piece.type.toUpperCase() : piece.type.toLowerCase()
        ctx.fillStyle = piece.color === "w" ? "#fff" : "#000"
        ctx.strokeStyle = piece.color === "w" ? "#000" : "#fff"
        ctx.lineWidth = 1
        ctx.strokeText(PIECE_CHARS[key], displayFile * SQ + SQ / 2, displayRank * SQ + SQ / 2)
        ctx.fillText(PIECE_CHARS[key], displayFile * SQ + SQ / 2, displayRank * SQ + SQ / 2)
      }
    }
    ctx.globalAlpha = 1.0

    // Phantom pieces from scan position (semi-transparent, only pieces that differ)
    if (phantomBoard) {
      ctx.globalAlpha = 0.7
      ctx.font = `${SQ * 0.75}px serif`
      for (let rank = 0; rank < 8; rank++) {
        for (let file = 0; file < 8; file++) {
          const phantomPiece = phantomBoard[rank][file]
          const realPiece = board[rank][file]
          // Only draw phantom where it differs from real
          const same = phantomPiece && realPiece
            && phantomPiece.type === realPiece.type
            && phantomPiece.color === realPiece.color
          if (same) continue
          if (!phantomPiece) continue
          const displayFile = g.flipped ? 7 - file : file
          const displayRank = g.flipped ? 7 - rank : rank
          const key = phantomPiece.color === "w" ? phantomPiece.type.toUpperCase() : phantomPiece.type.toLowerCase()
          // Cyan tint for phantom pieces to distinguish from real
          ctx.fillStyle = phantomPiece.color === "w" ? "#88ddff" : "#0088aa"
          ctx.strokeStyle = phantomPiece.color === "w" ? "#005577" : "#88ddff"
          ctx.lineWidth = 1.5
          ctx.strokeText(PIECE_CHARS[key], displayFile * SQ + SQ / 2, displayRank * SQ + SQ / 2)
          ctx.fillText(PIECE_CHARS[key], displayFile * SQ + SQ / 2, displayRank * SQ + SQ / 2)
        }
      }
      ctx.globalAlpha = 1.0
    }

    // Engine arrows (match against the scan position if active, otherwise the board)
    const arrowFen = showingPhantom ? scanFen : g.chess.fen()
    if (analysis.lines.length > 0 && analysis.fen === arrowFen) {
      for (let i = Math.min(analysis.lines.length, 3) - 1; i >= 0; i--) {
        const line = analysis.lines[i]
        if (!line || !line.pv[0]) continue
        const parsed = parseUciMove(line.pv[0])
        if (!parsed) continue
        const from = squareToCoords(parsed.from, g.flipped)
        const to = squareToCoords(parsed.to, g.flipped)
        drawArrow(ctx, from.x + SQ / 2, from.y + SQ / 2, to.x + SQ / 2, to.y + SQ / 2, ARROW_COLORS[i], i === 0 ? 6 : 4)
      }
    }

    // Draw dragged piece
    if (dragRef.current) {
      const drag = dragRef.current
      const key = drag.piece[0] === "w" ? drag.piece[1].toUpperCase() : drag.piece[1].toLowerCase()
      ctx.fillStyle = drag.piece[0] === "w" ? "#fff" : "#000"
      ctx.strokeStyle = drag.piece[0] === "w" ? "#000" : "#fff"
      ctx.lineWidth = 1
      ctx.strokeText(PIECE_CHARS[key], drag.x, drag.y)
      ctx.fillText(PIECE_CHARS[key], drag.x, drag.y)
    }

    rafRef.current = requestAnimationFrame(draw)
  }, [])

  function drawArrow(ctx, x1, y1, x2, y2, color, width) {
    const dx = x2 - x1
    const dy = y2 - y1
    const len = Math.hypot(dx, dy)
    if (len < 1) return
    const nx = dx / len
    const ny = dy / len
    const headLen = width * 3

    ctx.strokeStyle = color
    ctx.fillStyle = color
    ctx.lineWidth = width
    ctx.lineCap = "round"

    // Line
    ctx.beginPath()
    ctx.moveTo(x1, y1)
    ctx.lineTo(x2 - nx * headLen, y2 - ny * headLen)
    ctx.stroke()

    // Arrowhead
    ctx.beginPath()
    ctx.moveTo(x2, y2)
    ctx.lineTo(x2 - nx * headLen - ny * width * 1.5, y2 - ny * headLen + nx * width * 1.5)
    ctx.lineTo(x2 - nx * headLen + ny * width * 1.5, y2 - ny * headLen - nx * width * 1.5)
    ctx.closePath()
    ctx.fill()
  }

  // Animation loop
  useEffect(() => {
    rafRef.current = requestAnimationFrame(draw)
    return () => cancelAnimationFrame(rafRef.current)
  }, [draw])

  // Gambit scan — tree-searching version
  const scanForGambits = useCallback(async () => {
    const g = gameRef.current
    const engine = engineRef.current
    if (!g || !engine || !engineReady) return

    const scan = gambitScanRef.current
    if (scan.running) {
      scan.aborted = true
      return
    }

    scan.running = true
    scan.aborted = false
    setScanStatus("Starting scan...")
    setGambitResults([])
    gambitResultsRef.current = []
    setViewingScanIndex(null)

    // Stop continuous analysis and clear displayed arrows/eval
    sendToEngine(engine, "stop")
    analysisRef.current = { depth: 0, lines: [], fen: "" }
    setEvalDisplay("")
    setEngineLines([])
    setEngineDepth(0)

    const rootFen = g.chess.fen()

    // Update the phantom position display for the scan
    function showScanPosition(fenStr) {
      scanPositionRef.current = fenStr
      analysisRef.current = { depth: 0, lines: [], fen: fenStr }
    }

    // Helper: run engine and collect result
    function engineEval(worker, fenStr, depth, multiPV) {
      return new Promise((resolve) => {
        const results = []
        let bestmoveReceived = false
        const handler = (e) => {
          const msg = typeof e === "string" ? e : e.data
          if (typeof msg !== "string") return
          if (msg.startsWith("info") && msg.includes(" pv ")) {
            const d = msg.match(/\bdepth (\d+)/)
            const s = msg.match(/\bscore (cp|mate) (-?\d+)/)
            const pv = msg.match(/ pv (.+)/)
            const mpv = msg.match(/\bmultipv (\d+)/)
            if (d && s && pv) {
              const pvIdx = mpv ? parseInt(mpv[1]) - 1 : 0
              const score = s[1] === "mate" ? { mate: parseInt(s[2]) } : { cp: parseInt(s[2]) }
              results[pvIdx] = { depth: parseInt(d[1]), score, pv: pv[1].split(" ") }
            }
          }
          if (msg.startsWith("bestmove") && !bestmoveReceived) {
            bestmoveReceived = true
            worker.removeEventListener("message", handler)
            resolve(results.filter(Boolean))
          }
        }
        worker.addEventListener("message", handler)
        sendToEngine(worker, "setoption name Skill Level value 20")
        sendToEngine(worker, "setoption name MultiPV value " + (multiPV || 1))
        sendToEngine(worker, "position fen " + fenStr)
        sendToEngine(worker, "go depth " + depth)
      })
    }

    // Evaluate what happens after a specific opponent response to the gambit.
    // Returns { uci, san, continuationSan, evalCp, evalText, isTrap }
    // evalCp is from the gambiter's perspective after their best followup.
    // isTrap = true if the gambiter ends up better than before the gambit.
    async function evaluateResponse(afterFen, responseUci, beforeEvalCp) {
      const respChess = new Chess(afterFen)
      const respParsed = parseUciMove(responseUci)
      if (!respParsed) return null
      let respSan
      try {
        const m = respChess.move(respParsed)
        if (!m) return null
        respSan = m.san
      } catch { return null }

      // Now it's the gambiter's turn — get their best continuation
      const respFen = respChess.fen()
      const results = await engineEval(engine, respFen, Math.min(maxDepth, 14), 1)
      if (scan.aborted || results.length === 0) return null

      const pv = results[0].pv
      const score = results[0].score

      // Convert PV to SAN (up to 4 moves)
      const contChess = new Chess(respFen)
      const contSan = []
      for (const uci of pv.slice(0, 4)) {
        const p = parseUciMove(uci)
        if (!p) break
        try {
          const cm = contChess.move(p)
          if (cm) contSan.push(cm.san)
          else break
        } catch { break }
      }

      // Eval from gambiter's perspective (side to move at respFen)
      const evalCp = score.cp !== undefined ? score.cp : (score.mate > 0 ? 10000 : -10000)

      let evalText
      if (score.mate !== undefined) {
        evalText = `M${score.mate}`
      } else {
        evalText = (score.cp >= 0 ? "+" : "") + (score.cp / 100).toFixed(1)
      }

      // Trap = gambiter ends up better than before the gambit
      const isTrap = beforeEvalCp !== null ? evalCp > beforeEvalCp : evalCp > 0

      return { uci: responseUci, san: respSan, continuationSan: contSan, evalCp, evalText, isTrap }
    }

    // Check if a specific move from a position is a gambit opportunity
    async function checkGambit(beforeFen, move, leadingMoves, beforeEvalCp, knownEvalAfter) {
      const tempChess = new Chess(beforeFen)
      const moveObj = parseUciMove(move)
      if (!moveObj) return null
      let sanMove
      try {
        const m = tempChess.move(moveObj)
        if (!m) return null
        sanMove = m.san
      } catch { return null }
      const afterFen = tempChess.fen()

      // Show this position as the phantom board so arrows make sense
      showScanPosition(afterFen)

      // Use pre-computed eval if available (from MultiPV scan), otherwise evaluate
      // This eval is from the OPPONENT's perspective (side to move after gambit)
      let evalAfter
      if (knownEvalAfter) {
        evalAfter = knownEvalAfter
      } else {
        const fullResults = await engineEval(engine, afterFen, Math.min(maxDepth, 12), 1)
        if (scan.aborted || fullResults.length === 0) return null
        evalAfter = fullResults[0].score
      }

      // Is it bad relative to before the move? (swing = how much worse for us)
      // beforeEvalCp is from gambiter's perspective, evalAfter.cp from opponent's
      const isBadForUs = evalAfter.mate !== undefined
        ? (evalAfter.mate > 0)
        : beforeEvalCp !== null
          ? (beforeEvalCp + evalAfter.cp) > gambitThreshold
          : evalAfter.cp > gambitThreshold

      if (!isBadForUs) return null

      // Calculate cost text
      let swingText
      if (evalAfter.mate !== undefined) {
        swingText = `sacrifices for M${Math.abs(evalAfter.mate)}`
      } else if (beforeEvalCp !== null) {
        const swingCp = beforeEvalCp + evalAfter.cp
        swingText = (swingCp / 100).toFixed(1) + " pawns"
      } else {
        swingText = (evalAfter.cp / 100).toFixed(1) + " pawns"
      }

      // Get opponent's top responses with MultiPV
      const strongLines = await engineEval(engine, afterFen, maxDepth, 4)
      if (scan.aborted) return null

      // For each opponent response, check if it's a refutation or a trap
      const traps = []
      const refutations = []

      for (const line of strongLines) {
        if (scan.aborted) return null
        const responseUci = line.pv[0]
        if (!responseUci) continue

        const result = await evaluateResponse(afterFen, responseUci, beforeEvalCp)
        if (!result || scan.aborted) continue

        if (result.isTrap) {
          traps.push(result)
        } else {
          refutations.push(result)
        }
      }

      // Must have at least one trap line — otherwise this isn't a useful gambit
      if (traps.length === 0) return null

      const totalResponses = traps.length + refutations.length
      const trapDensity = totalResponses > 0 ? traps.length / totalResponses : 0

      // Build the gambit result
      const gambit = {
        leadingMoves,
        san: sanMove,
        from: moveObj.from,
        to: moveObj.to,
        promotion: moveObj.promotion,
        swingText,
        trapDensity,
        trapCount: traps.length,
        refutationCount: refutations.length,
        traps: traps.map(t => ({
          san: t.san,
          continuation: t.continuationSan.join(" "),
          evalText: t.evalText,
          // Recovery: how much the trap claws back from the gambit's cost
          // evalAfter.cp = opponent's advantage after gambit, t.evalCp = gambiter's eval after trap
          recovery: t.evalCp !== undefined && evalAfter.cp !== undefined
            ? ((t.evalCp + evalAfter.cp) / 100).toFixed(1)
            : null,
        })),
        refutations: refutations.map(r => r.san),
      }

      return gambit
    }

    const foundGambits = []
    let nodesExplored = 0

    // Recursive tree search
    async function explore(fenStr, depth, leadingMoves) {
      if (scan.aborted || depth <= 0) return

      const chess = new Chess(fenStr)
      if (chess.game_over()) return

      const allMoves = chess.moves({ verbose: true })
      const allUci = allMoves.map(m => m.from + m.to + (m.promotion || ""))

      // Single MultiPV eval for all legal moves at low depth — fast filtering pass
      showScanPosition(fenStr)
      const numPV = Math.max(allUci.length, branchWidth)
      const multiPvResults = await engineEval(engine, fenStr, Math.min(maxDepth, 8), numPV)
      if (scan.aborted || multiPvResults.length === 0) return

      // Best move's eval = beforeEvalCp (from side-to-move's perspective)
      const beforeEvalCp = multiPvResults[0].score.cp !== undefined
        ? multiPvResults[0].score.cp : null

      // Filter to gambit candidates: moves significantly worse than the best
      const gambitCandidates = []
      for (const line of multiPvResults) {
        const moveUci = line.pv[0]
        if (!moveUci) continue

        // Eval is from side-to-move (gambiter) perspective; opponent's perspective is negated
        const opponentScore = {}
        if (line.score.mate !== undefined) {
          opponentScore.mate = -line.score.mate
        } else {
          opponentScore.cp = -line.score.cp
        }

        // Check relative swing, not absolute eval
        const isBadForUs = opponentScore.mate !== undefined
          ? (opponentScore.mate > 0)
          : beforeEvalCp !== null
            ? (beforeEvalCp + opponentScore.cp) > gambitThreshold
            : opponentScore.cp > gambitThreshold

        if (isBadForUs) {
          gambitCandidates.push({ uci: moveUci, opponentScore })
        }
      }

      // Check only gambit candidates (skip the rest)
      for (let i = 0; i < gambitCandidates.length; i++) {
        if (scan.aborted) return
        const candidate = gambitCandidates[i]
        nodesExplored++
        const moveIdx = allUci.indexOf(candidate.uci)
        const san = moveIdx >= 0 ? allMoves[moveIdx].san : candidate.uci
        setScanStatus(`Depth ${leadingMoves.length}/${lookAhead} · ${san} (${gambitCandidates.length} candidates) · ${nodesExplored} positions · ${foundGambits.length} found`)

        const gambit = await checkGambit(fenStr, candidate.uci, leadingMoves, beforeEvalCp, candidate.opponentScore)
        if (gambit) {
          foundGambits.push(gambit)
          gambitResultsRef.current = [...foundGambits]
          setGambitResults([...foundGambits])
        }
      }

      // Deeper exploration using top moves from the same MultiPV results
      if (depth > 1) {
        const topMoves = multiPvResults.slice(0, branchWidth).map(r => r.pv[0]).filter(Boolean)

        for (const uci of topMoves) {
          if (scan.aborted) return
          const chess2 = new Chess(fenStr)
          const parsed = parseUciMove(uci)
          if (!parsed) continue
          let san
          try {
            const m = chess2.move(parsed)
            if (!m) continue
            san = m.san
          } catch { continue }

          await explore(chess2.fen(), depth - 1, [...leadingMoves, san])
        }
      }
    }

    await explore(rootFen, lookAhead, [])

    scan.running = false
    scanPositionRef.current = null
    const statusMsg = scan.aborted
      ? "Scan cancelled."
      : `Done. ${nodesExplored} positions explored, ${foundGambits.length} gambit(s) found.`
    setScanStatus(statusMsg)

    // Save to scan history if we found any gambits
    if (foundGambits.length > 0) {
      const moveNum = g.moveHistory.length - 1
      const turnLabel = new Chess(rootFen).turn() === "w" ? "White" : "Black"
      const label = `#${scanHistory.length + 1}: ${turnLabel} move ${Math.ceil(moveNum / 2) || 1} · ${foundGambits.length} gambit(s)`
      setScanHistory(prev => [...prev, { label, results: [...foundGambits], rootFen }])
    }

    // Resume continuous analysis
    startAnalysis(rootFen)
  }, [engineReady, maxDepth, gambitThreshold, lookAhead, branchWidth, startAnalysis, scanHistory.length])

  // Play a gambit: first play the leading moves, then the gambit move
  const playGambit = useCallback((gambit) => {
    const g = gameRef.current
    if (!g) return
    // Reset to the position before the scan started (go back to root)
    // Navigate to current historyIndex first
    const rootIndex = g.historyIndex
    // Play each leading move
    for (const san of gambit.leadingMoves) {
      const moves = g.chess.moves({ verbose: true })
      const match = moves.find(m => m.san === san)
      if (match) {
        makeMove(match.from, match.to, match.promotion)
      } else break
    }
    // Play the gambit move itself
    makeMove(gambit.from, gambit.to, gambit.promotion)
  }, [makeMove])

  // Reset board
  const resetBoard = useCallback(() => {
    const g = gameRef.current
    if (!g) return
    g.chess.reset()
    g.moveHistory = [{ san: null, fen: g.chess.fen() }]
    g.historyIndex = 0
    g.selected = null
    setFen(g.chess.fen())
    setMoveList([{ san: null, fen: g.chess.fen() }].map(h => h.san))
    setHistoryIndex(0)
    setSelected(null)
    setGambitResults([])
    gambitResultsRef.current = []
  }, [])

  const controlStyle = {
    display: "flex",
    alignItems: "center",
    gap: 8,
    marginBottom: 8,
    fontSize: 13,
    fontFamily: "monospace",
    color: "#ccc",
  }

  const buttonStyle = {
    padding: "4px 10px",
    background: "#333",
    border: "1px solid #555",
    borderRadius: 4,
    color: "#ccc",
    fontSize: 12,
    fontFamily: "monospace",
    cursor: "pointer",
  }

  const sliderStyle = {
    width: 120,
    accentColor: "#888",
  }

  const labelStyle = {
    display: "inline-block",
    minWidth: 240,
  }

  return (
    <Layout>
      <head>
        <title>Chess Gambit Generator</title>
      </head>
      <div style={{ padding: "16px", fontFamily: "monospace", color: "#ccc", background: "#1a1a1a", minHeight: "100vh" }}>
        <h2 style={{ margin: "0 0 12px", fontSize: 18, color: "#fff" }}>Chess Gambit Generator</h2>

        {/* Controls */}
        <div style={{ marginBottom: 12 }}>
          <div style={controlStyle}>
            <button onClick={() => { const g = gameRef.current; if (g) { g.flipped = !g.flipped; setFlipped(f => !f) } }} style={buttonStyle}>
              Flip Board
            </button>
            <button onClick={resetBoard} style={buttonStyle}>Reset</button>
            <button onClick={() => navigateTo(historyIndex - 1)} style={buttonStyle}>&larr;</button>
            <button onClick={() => navigateTo(historyIndex + 1)} style={buttonStyle}>&rarr;</button>
            <span style={{ color: "#666", marginLeft: 8 }}>
              {engineReady ? `Depth: ${engineDepth}` : "Loading engine..."}
            </span>
            <span style={{ color: evalDisplay.startsWith("-") ? "#e88" : evalDisplay.startsWith("+") ? "#8e8" : "#aaa", fontWeight: "bold", marginLeft: 4 }}>
              {evalDisplay}
            </span>
          </div>

          <div style={controlStyle}>
            <label style={labelStyle}>Gambit Threshold: {(gambitThreshold / 100).toFixed(1)} pawns</label>
            <input type="range" min={10} max={300} step={10} value={gambitThreshold} onChange={e => setGambitThreshold(parseInt(e.target.value))} style={sliderStyle} />
          </div>
          <div style={controlStyle}>
            <label style={labelStyle}>Max Search Depth: {maxDepth}</label>
            <input type="range" min={8} max={25} value={maxDepth} onChange={e => setMaxDepth(parseInt(e.target.value))} style={sliderStyle} />
          </div>
          <div style={controlStyle}>
            <label style={labelStyle}>Look-ahead: {lookAhead} ply</label>
            <input type="range" min={1} max={5} value={lookAhead} onChange={e => setLookAhead(parseInt(e.target.value))} style={sliderStyle} />
            <span style={{ color: "#666", fontSize: 11 }}>Moves deep to search (warning: time-intensive)</span>
          </div>
          <div style={controlStyle}>
            <label style={labelStyle}>Branch width: {branchWidth}</label>
            <input type="range" min={2} max={10} value={branchWidth} onChange={e => setBranchWidth(parseInt(e.target.value))} style={sliderStyle} />
            <span style={{ color: "#666", fontSize: 11 }}>Top moves explored per ply</span>
          </div>
          <div style={controlStyle}>
            <button onClick={scanForGambits} style={{ ...buttonStyle, background: gambitScanRef.current.running ? "#633" : "#363", borderColor: gambitScanRef.current.running ? "#a55" : "#5a5" }}>
              {gambitScanRef.current.running ? "Cancel Scan" : "Scan for Gambits"}
            </button>
            <span style={{ color: "#888", fontSize: 12 }}>{scanStatus}</span>
          </div>
        </div>

        {/* Main layout */}
        <div style={{ display: "flex", gap: 16, flexWrap: "wrap" }}>
          {/* Board */}
          <canvas
            ref={canvasRef}
            width={BOARD_SIZE}
            height={BOARD_SIZE}
            onMouseDown={handleMouseDown}
            onMouseMove={handleMouseMove}
            onMouseUp={handleMouseUp}
            style={{
              width: BOARD_SIZE,
              height: BOARD_SIZE,
              cursor: "pointer",
              borderRadius: 4,
              border: "2px solid #444",
            }}
          />

          {/* Side panel */}
          <div style={{ width: 280, fontSize: 13 }}>
            {/* Engine lines */}
            <div style={{ marginBottom: 12 }}>
              <div style={{ color: "#888", marginBottom: 4, fontSize: 11, textTransform: "uppercase" }}>Engine Lines</div>
              {engineLines.map((line, i) => (
                <div key={i} style={{ marginBottom: 2, color: i === 0 ? "#ccc" : "#777" }}>
                  <span style={{ color: line.score.startsWith("-") ? "#e88" : line.score.startsWith("+") ? "#8e8" : "#aaa", fontWeight: "bold", marginRight: 6 }}>
                    {line.score}
                  </span>
                  {line.moves}
                </div>
              ))}
            </div>

            {/* Gambit results — live or from scan history */}
            {(() => {
              const displayResults = viewingScanIndex !== null
                ? scanHistory[viewingScanIndex]?.results || []
                : gambitResults
              const isHistorical = viewingScanIndex !== null
              if (displayResults.length > 0) return (
                <div style={{ marginBottom: 12 }}>
                  <div style={{ color: "#f80", marginBottom: 4, fontSize: 11, textTransform: "uppercase", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                    <span>{isHistorical ? scanHistory[viewingScanIndex]?.label : "Gambit Opportunities"}</span>
                    {isHistorical && (
                      <span
                        onClick={() => setViewingScanIndex(null)}
                        style={{ cursor: "pointer", color: "#888", fontSize: 10 }}
                      >
                        [close]
                      </span>
                    )}
                  </div>
                  {displayResults.map((gb, i) => (
                    <div
                      key={i}
                      onClick={() => {
                        setInspectedGambit(inspectedGambit === i ? null : i)
                        // Load the root position for this scan first if viewing history
                        if (isHistorical) {
                          const entry = scanHistory[viewingScanIndex]
                          if (entry) {
                            const g = gameRef.current
                            if (g) {
                              g.chess.load(entry.rootFen)
                              g.moveHistory = g.moveHistory.slice(0, g.historyIndex + 1)
                              g.moveHistory.push({ san: null, fen: entry.rootFen })
                              g.historyIndex = g.moveHistory.length - 1
                              setFen(entry.rootFen)
                              setMoveList(g.moveHistory.map(h => h.san))
                              setHistoryIndex(g.historyIndex)
                            }
                          }
                        }
                        playGambit(gb)
                      }}
                      style={{
                        padding: "4px 6px",
                        marginBottom: 4,
                        background: inspectedGambit === i ? "#3a2a00" : "#2a1a00",
                        border: `1px solid ${inspectedGambit === i ? "#885500" : "#553300"}`,
                        borderLeft: inspectedGambit === i ? "3px solid #f80" : "1px solid #553300",
                        borderRadius: 3,
                        cursor: "pointer",
                        color: "#ddd",
                      }}
                    >
                      <div style={{ fontWeight: "bold", color: "#f80" }}>
                        {gb.leadingMoves.length > 0 && (
                          <span style={{ fontWeight: "normal", color: "#999" }}>{gb.leadingMoves.join(" ")} </span>
                        )}
                        {gb.san}
                        <span style={{ fontWeight: "normal", color: "#888" }}> (cost: {gb.swingText})</span>
                      </div>
                      <div style={{ fontSize: 11, color: "#999", marginTop: 2 }}>
                        <span style={{ color: gb.trapDensity >= 0.5 ? "#6b6" : "#b86" }}>
                          {Math.round(gb.trapDensity * 100)}% trap density
                        </span>
                        {" "}({gb.trapCount} trap{gb.trapCount !== 1 ? "s" : ""}, {gb.refutationCount} refutation{gb.refutationCount !== 1 ? "s" : ""}{gb.refutations.length > 0 ? ": " + gb.refutations.join(", ") : ""})
                      </div>
                      {gb.traps && gb.traps.map((trap, ti) => (
                        <div key={ti} style={{ fontSize: 11, marginTop: 3, padding: "3px 5px", background: "#1a2a10", borderRadius: 2, borderLeft: "2px solid #4a4" }}>
                          <span style={{ color: "#6b6" }}>after </span>
                          <span style={{ color: "#aaa" }}>{trap.san}: </span>
                          <span style={{ color: "#ccc" }}>{trap.continuation} </span>
                          <span style={{
                            color: trap.evalText.startsWith("+") || trap.evalText.startsWith("M") ? "#8e8"
                              : trap.evalText.startsWith("-") ? "#e88" : "#aaa",
                            fontWeight: "bold",
                          }}>
                            ({trap.evalText})
                          </span>
                          {trap.recovery && (
                            <span style={{ color: "#6b6", marginLeft: 4 }}>
                              recovers {trap.recovery}
                            </span>
                          )}
                        </div>
                      ))}
                    </div>
                  ))}
                </div>
              )
              return null
            })()}

            {/* Scan history */}
            {scanHistory.length > 0 && (
              <div style={{ marginBottom: 12 }}>
                <div style={{ color: "#888", marginBottom: 4, fontSize: 11, textTransform: "uppercase" }}>Scan History</div>
                {scanHistory.map((entry, i) => (
                  <div
                    key={i}
                    onClick={() => {
                      setViewingScanIndex(i)
                      // Restore the board to the position when this scan was run
                      const g = gameRef.current
                      if (g && entry.rootFen) {
                        g.chess.load(entry.rootFen)
                        g.moveHistory = g.moveHistory.slice(0, g.historyIndex + 1)
                        g.moveHistory.push({ san: null, fen: entry.rootFen })
                        g.historyIndex = g.moveHistory.length - 1
                        g.selected = null
                        setFen(entry.rootFen)
                        setMoveList(g.moveHistory.map(h => h.san))
                        setHistoryIndex(g.historyIndex)
                        setSelected(null)
                      }
                    }}
                    style={{
                      padding: "3px 6px",
                      marginBottom: 2,
                      background: viewingScanIndex === i ? "#2a2a00" : "#1a1a1a",
                      border: `1px solid ${viewingScanIndex === i ? "#555500" : "#333"}`,
                      borderRadius: 3,
                      cursor: "pointer",
                      color: viewingScanIndex === i ? "#ee8" : "#888",
                      fontSize: 11,
                    }}
                  >
                    {entry.label}
                  </div>
                ))}
              </div>
            )}

            {/* Move history */}
            <div>
              <div style={{ color: "#888", marginBottom: 4, fontSize: 11, textTransform: "uppercase" }}>Moves</div>
              <div style={{ maxHeight: 200, overflowY: "auto", lineHeight: 1.8 }}>
                {moveList.slice(1).map((san, i) => {
                  const moveNum = Math.floor(i / 2) + 1
                  const isWhite = i % 2 === 0
                  return (
                    <span key={i}>
                      {isWhite && <span style={{ color: "#666" }}>{moveNum}. </span>}
                      <span
                        onClick={() => navigateTo(i + 1)}
                        style={{
                          cursor: "pointer",
                          color: i + 1 === historyIndex ? "#fff" : "#999",
                          fontWeight: i + 1 === historyIndex ? "bold" : "normal",
                          marginRight: 4,
                        }}
                      >
                        {san}
                      </span>
                    </span>
                  )
                })}
              </div>
            </div>
          </div>
        </div>
      </div>
    </Layout>
  )
}
